import json,re,sys
from pathlib import Path
from genlayer_py import create_account,create_client
from genlayer_py.chains import studionet
R=Path(__file__).parents[1];text=(R.parents[3]/"accounts.env").read_text();key=re.search(r'^ACCOUNT_7_GENLAYER_PRIVATE_KEY\s*=\s*"?([^"\r\n]+)',text,re.M).group(1).strip();client=create_client(chain=studionet,account=create_account(account_private_key=key));address=sys.argv[1];room="HARVEST-12";args=[room,"A neighborhood welcome supper for returning volunteers and first-time guests.",["Mara: wheelchair user, garden volunteer, likes practical projects","Idris: first-time guest, quiet, interested in food history","June: returning volunteer, lively storyteller, avoids loud corners","Theo: first-time guest, patient listener, knows community gardens"],[4,4],["Keep the aisle-side chair at Table A available to the guest who needs step-free access","Do not seat two first-time guests alone without a returning volunteer","Distribute strong storytellers across tables"],3];tx=client.write_contract(address=address,function_name="set_table",args=args);print("set_table_tx="+str(tx),flush=True);receipt=client.wait_for_transaction_receipt(transaction_hash=tx,wait_until="finalized",retries=180,interval=5000,full_transaction=True);print(json.dumps({"tx":str(tx),"result":receipt.get("result_name")},default=str),flush=True);print(json.dumps(client.read_contract(address=address,function_name="get_dinner",args=[room]),default=str),flush=True)
